package social

// `state` binds the browser's return to the starting device; PKCE (S256, Google/Microsoft) and the OIDC
// nonce (all providers) bind the provider's answer to the same attempt. A code leaked from the browser leg
// is unredeemable without the verifier, and an id_token minted for another sign-in is refused even with a
// perfect signature. Both are generated by scd per attempt, stored with the state row, and used once.

import (
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"fmt"
)

// NewAttemptSecrets returns a PKCE verifier and/or nonce per the provider's bindings ("" for unused). Each
// is 32 random bytes as 43 base64url characters, the RFC 7636 minimum verifier length.
func NewAttemptSecrets(b Binding) (verifier, nonce string, err error) {
	if b.PKCE {
		if verifier, err = random43(); err != nil {
			return "", "", err
		}
	}
	if b.Nonce {
		if nonce, err = random43(); err != nil {
			return "", "", err
		}
	}
	return verifier, nonce, nil
}

func random43() (string, error) {
	var b [32]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b[:]), nil
}

// PKCEChallengeS256 is the RFC 7636 S256 transform.
func PKCEChallengeS256(verifier string) string {
	sum := sha256.Sum256([]byte(verifier))
	return base64.RawURLEncoding.EncodeToString(sum[:])
}

// requireBinding refuses an exchange missing what the provider binds an attempt with.
func requireBinding(b Binding, x ExchangeRequest) error {
	if b.PKCE && x.CodeVerifier == "" {
		return fmt.Errorf("%w: no PKCE verifier", ErrAttemptBinding)
	}
	if b.Nonce && x.Nonce == "" {
		return fmt.Errorf("%w: no nonce", ErrAttemptBinding)
	}
	return nil
}

// checkNonce compares in constant time so the comparison gives no timing hint about the nonce.
func checkNonce(c *idClaims, want string) error {
	got := c.str("nonce")
	if want == "" || got == "" || subtle.ConstantTimeCompare([]byte(got), []byte(want)) != 1 {
		return fmt.Errorf("%w: id_token nonce does not match this sign-in attempt", ErrAttemptBinding)
	}
	return nil
}
